Q: Get the length of a SVG line,rect,polygon and circle tags A: <h2>TL;DR: use native JS method <code>getTotalLength()</code> for browser applications</h2>
<p>All browser support this for many years - see <a href="https://caniuse.com/?search=getTotalLength" rel="nofollow noreferrer">caniuse statistics</a>. Geometry elements are kind of a super-class including shapes and path elements – but excluding other rendered elements such as <code>&lt;text&gt;</code>.<br />
You can apply it to all SVG geometry elements:</p>
<ul>
<li><code>&lt;path&gt;</code>,</li>
<li><code>&lt;circle&gt;</code>, <code>&lt;ellipse&gt;</code>,</li>
<li><code>&lt;polygon&gt;</code>, <code>&lt;polyline&gt;</code>, <code>&lt;line&gt;</code></li>
<li><code>&lt;rect&gt;</code></li>
</ul>
<pre class="lang-js prettyprint-override"><code>const totalLength = element.getTotalLength();
</code></pre>
<p>However, this method is <strong>only available in browser</strong> so you can't use it in headless environments such as node.js.</p>
<h2>Problem 1: SVG primitives support relative or physical units!</h2>
<p>In other words we can't take for granted all shape attribute values are in user units we can use for perimeter/circumference calculations.</p>
<h3>Primitives and shapes</h3>
<p>Simplified: the term »primitive« is used for basic shapes with a discrete number of parameters describing the rendered shape.</p>
<p>In SVG primitives would be <code>&lt;circle&gt;</code>, <code>&lt;ellipse&gt;</code>, <code>&lt;polygon&gt;</code>, <code>&lt;polyline&gt;</code>, <code>&lt;line&gt;</code>, <code>&lt;rect&gt;</code> – any geometry of these types can be expressed by a predefined number of parameters.</p>
<p>This excludes <code>&lt;polygon&gt;</code> and <code>&lt;polyline&gt;</code> as it's shape is described by the <code>points</code> attribute which can contain arbitrary amounts of vertices coordinates.</p>
<p>That said – polygons are quite trivial as we can take for granted all values describe absolute x/y coordinates.</p>
<h2>Convert relative or physical units to absolute</h2>
<h3>Physical units</h3>
<p>These means units such as <code>in</code>, <code>mm</code>, <code>pt</code> etc.
For many years most applications have agreed on a pixel to inch ratio of 96dpi. Which is actually rather an arbitrary convention and by no means self-explanatory. For instance Adobe eco-systems still use a 72 dpi ratio e.g for pdf.</p>
<p><div class="snippet" data-lang="js" data-hide="true" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code snippet-currently-hidden">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// show original SVG markup
original.value = new XMLSerializer().serializeToString(svg1);

// normalize to user unit
normalizePrimitivesValues(svg2, 150, 30);

// show normalized SVG markup
output.value = new XMLSerializer().serializeToString(svg2)


function normalizePrimitivesValues(svg, w = 0, h = 0) {
  let els = svg.querySelectorAll("rect, line, ellipse, circle");
  const geoAtts = {
    line: ["x1", "y1", "x2", "y2"],
    circle: ["cx", "cy", "r"],
    ellipse: ["cx", "cy", "rx", "ry"],
    rect: ["x", "y", "width", "height", "rx", "ry"]
  };

  const horizontalAtts = ["x", "x1", "x2", "cx", "rx", "width"];
  const verticalAtts = ["y", "y1", "y2", "cy", "ry", "height"];

  els.forEach((el) =&gt; {
    let type = el.nodeName;

    // convert values to user unit
    for(let i=0; i&lt; geoAtts[type].length; i++){
      let att = geoAtts[type][i];
      if(!el.hasAttribute(att)) continue;

      let val = el.getAttribute(att);
      let valNum = parseFloat(val);
      let unit = getUnit(val);
      let isHorizontal = horizontalAtts.includes(att);
      let isVertical = verticalAtts.includes(att);
      let normalizedDiagonal = att==='r'

      let valueAbs = convertValueToUserunit(valNum,{
        unit, isHorizontal, isVertical, width:w, height:h, normalizedDiagonal
      })
      el.setAttribute(att, valueAbs)
    };
  });
}

function convertValueToUserunit(
  value = 0,
  {
    unit = "",
    width = 0,
    height = 0,
    isHorizontal = false,
    isVertical = false,
    normalizedDiagonal = false,
    dpi = 96,
    fontSize = 16
  } = {}
) {
  if (!unit) return value;

  // used for normalized diagonal conversion - e.g circle r
  const scaleRoot =
    width &amp;&amp; height
      ? Math.sqrt(width * width + height * height) / Math.sqrt(2)
      : 1;

  // 1/2.54
  const inch2cm = 0.39370078;
  // 1/72
  const inch2pt = 0.01388889;

  switch (unit) {
    case "%":
      if (width &amp;&amp; isHorizontal) {
        scale = width / 100;
      } else if (height &amp;&amp; isVertical) {
        scale = height / 100;
      } else {
        scale = normalizedDiagonal ? scaleRoot / 100 : 1;
      }
      break;
    case "in":
      scale = dpi;
      break;

    case "pt":
      // 1/72
      scale = dpi * inch2pt;
      break;

    case "pc":
      // 1/6
      scale = dpi * 0.16666667;
      break;

    case "cm":
      // 1/2.54
      scale = inch2cm * dpi;
      break;
    case "mm":
      scale = inch2cm * dpi * 0.1;
      break;

    // just a default approximation
    case "em":
    case "rem":
      scale = fontSize;
      break;
    default:
      scale = 1;
  }
  return value * scale;
}

function getUnit(val) {
  if (!val || !isNaN(val)) return "";
  val = val.replace(/\+|\-/g, "");
  let unit = val.match(/[^\d|.]+/g)[0];
  return unit;
}</code></pre>
