<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;h3&gt;Relative or physical unit&lt;/h3&gt;
&lt;svg id="svg1" viewBox="0 0 150 30" fill="none" stroke="#E3000F"&gt;
  &lt;polygon points="7.9 22.8 3,14.3 7.9,5.8 17.6,5.8 22.5,14.3 17.6,22.8 " /&gt;
  &lt;polyline points="40.9,22.8 31.1,22.8 26.2,14.3 31.1,5.8 40.9,5.8 45.8,14.3 " /&gt;
  &lt;rect x="37.5%" y="20%" rx="5%" ry="6%" width="6%" height="56%" /&gt;
  &lt;line x1="32%" y1="22.8" x2="52.5" y2="5.8" /&gt;
  &lt;circle cx="52%" cy="49%" r="8%" /&gt;
  &lt;ellipse cx="68%" cy="49%" rx="7%" ry="25%" /&gt;
  &lt;rect x="78%" y="25%"  fill="none" stroke="#E3000F" width="15" height="0.15625in" /&gt;
  &lt;line x1="90%" y1="50%" x2="95%" y2="50%" /&gt;
  &lt;line x1="95%" y1="50%" x2="95%" y2="60%" /&gt;
&lt;/svg&gt;

&lt;h3&gt;Converted to user unit&lt;/h3&gt;
&lt;svg id="svg2" viewBox="0 0 150 30" fill="none" stroke="#E3000F"&gt;
  &lt;polygon points="7.9 22.8 3,14.3 7.9,5.8 17.6,5.8 22.5,14.3 17.6,22.8 " /&gt;
  &lt;polyline points="40.9,22.8 31.1,22.8 26.2,14.3 31.1,5.8 40.9,5.8 45.8,14.3 " /&gt;
  &lt;rect x="37.5%" y="20%" rx="5%" ry="6%" width="6%" height="56%" /&gt;
  &lt;line x1="32%" y1="22.8" x2="52.5" y2="5.8" /&gt;
  &lt;circle cx="52%" cy="49%" r="8%" /&gt;
  &lt;ellipse cx="68%" cy="49%" rx="7%" ry="25%" /&gt;
  &lt;rect x="78%" y="25%"  fill="none" stroke="#E3000F" width="15" height="0.15625in" /&gt;
  &lt;line x1="90%" y1="50%" x2="95%" y2="50%" /&gt;
  &lt;line x1="95%" y1="50%" x2="95%" y2="60%" /&gt;
&lt;/svg&gt;

&lt;h3&gt;Original&lt;/h3&gt;
&lt;textarea id="original" &gt;&lt;/textarea&gt;


&lt;h3&gt;Normalized&lt;/h3&gt;
&lt;textarea  id="output" &gt;&lt;/textarea&gt;</code></pre>
