</p>
<h3>Normalized diagonals</h3>
<p>Mostly we can separate attributes in horizontal or vertical values.<br />
For instance <code>x</code>, <code>x1</code>, <code>width</code> are obviously horizontal properties – if we have percentage based values these relate to the viewBox width. The same applies to vertical values relating to the SVG's height.</p>
<p>But some SVG attributes such as <code>r</code> used in <code>&lt;circle&gt;</code> expect a normalized diagonal value calculated like so:</p>
<pre class="lang-js prettyprint-override"><code>const normalizedDiagonalScale = Math.sqrt(width ** 2 + height ** 2) / Math.sqrt(2)
</code></pre>
<p>This calculation is not required for viewBoxes with a square aspect ratio.</p>
<p>In browser we could also retrieve the <a href="https://developer.mozilla.org/en-US/docs/Web/API/SVGAnimatedRect/baseVal" rel="nofollow noreferrer"><code>baseVal</code></a> properties which also return normalized values in user-units – but you can as well use <code>getTotalLength()</code>.</p>
<h2>Problem 2: <code>&lt;rect&gt;</code> also allows corner rounding</h2>
<p>To make things even worse we can specify different border-radii via <code>rx</code> and <code>ry</code> ... have I mentioned these attributes also allow relative or physical units?
So we also need to respect these to get an accurate perimeter length.<br />
... just one more thing: <code>rx</code> and <code>ry</code> may also use »nonsense« values so border radii that exceed half of the rect's width or height – we need to catch these exceptions as well. ... and we also need to check both attributes in case only <code>ry</code> is defined <code>ry===rx</code>.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="false" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// get length
let shapes = svg2.querySelectorAll("rect, line, ellipse, circle, polygon, polyline");

// calculate lengths for each shape
let report = []
shapes.forEach(shape =&gt; {
  let length = getShapePerimeter(shape);
  let lengthNative = shape.getTotalLength()
  report.push({
    nodeName: shape.nodeName,
    length,
    lengthNative
  })
})

lengthReport.value = JSON.stringify(report, null, ' ')


function getShapePerimeter(el) {
  const geoAtts = {
    line: ["x1", "y1", "x2", "y2"],
    circle: ["cx", "cy", "r"],
    ellipse: ["cx", "cy", "rx", "ry"],
    rect: ["x", "y", "width", "height", "rx", "ry"],
    polygon: ["points"],
    polyline: ["points"],
  };


  let type = el.nodeName;

  let atts = {}
  for (let i = 0; i &lt; geoAtts[type].length; i++) {
    let att = geoAtts[type][i];
    if (!el.hasAttribute(att)) continue;
    if (type === 'polygon' || type === 'polyline') {
      // poly atts also accept whitespace such as new lines or tabs as separators
      let pts = el.getAttribute(att).replace(/[\s,]+/g, ' ').split(' ').filter(Boolean).map(Number)
      atts[att] = pts;
    } else {
      atts[att] = parseFloat(el.getAttribute(att));
    }
  }

  let len = 0;
  switch (type) {
    case 'rect':
      let {
        width, height, rx = 0, ry = 0
      } = atts;
      let ellipsePerimeter = 0;
      // has corner rounding
      if (atts.rx || atts.ry) {
        rx = atts.rx ? atts.rx : atts.ry
        ry = atts.ry ? atts.ry : atts.rx

        // normalize too large corner radii
        if (rx &gt; width * 0.5) rx = width * 0.5;
        if (ry &gt; height * 0.5) ry = height * 0.5;

        width -= rx * 2
        height -= ry * 2
        ellipsePerimeter = getEllipsePerimeter(rx, ry)
      }
      len = width * 2 + height * 2 + ellipsePerimeter;
      break;
    case 'circle':
      len = Math.PI * 2 * atts.r
      break;
    case 'ellipse':
      len = getEllipsePerimeter(atts.rx, atts.ry)
      break;

    case 'polygon':
    case 'polyline':
      let isPoly = type === 'polygon';
      len = getPolygonLength(atts.points, isPoly)
      break;
    case 'line':
      let {
        x1, y1, x2, y2
      } = atts;
      len = getEuclideanDistance(x1, y1, x2, y2)
      break;

    default:
      len = 0;

  }

  return len;

}

function getPolygonLength(coords = [], isPoly = false) {
  let len = 0;
  let l = coords.length;
  let x1, y1, x2, y2;

  for (let i = 3; i &lt; l; i += 2) {
    [x1, y1, x2, y2] = [coords[i - 3], coords[i - 2], coords[i - 1], coords[i]]
    len += getEuclideanDistance(x1, y1, x2, y2);
  }

  // add closing line
  if (isPoly) {
    [x1, y1, x2, y2] = [coords[l - 2], coords[l - 1], coords[0], coords[1]]
    len += getEuclideanDistance(x1, y1, x2, y2)
  }
  return len
}


function getEuclideanDistance(x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  // horizontal or vertical
  if (!dx || !dy) return Math.abs(dx + dy)
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Ramanujan approximation
 * based on: https://www.mathsisfun.com/geometry/ellipse-perimeter.html#tool
 */
function getEllipsePerimeter(rx = 0, ry = 0) {
  // is circle
  if (rx === ry) {
    return 2 * Math.PI * rx;
  }

  let c = rx + ry
  let d = (rx - ry) / c;
  let h = d * d

  let totalLength = Math.PI * c * (1 + 3 * h / (10 + Math.sqrt(4 - 3 * h)));
  return totalLength;
};</code></pre>
