  &lt;polygon points="7.9 22.8 3,14.3 7.9,5.8 17.6,5.8 22.5,14.3 17.6,22.8 "/&gt;
  &lt;polyline points="40.9,22.8 31.1,22.8 26.2,14.3 31.1,5.8 40.9,5.8 45.8,14.3 "/&gt;
  &lt;rect x="56.25" y="6" rx="7.5" ry="1.7999999999999998" width="9" height="16.8"/&gt;
  &lt;line x1="48" y1="22.8" x2="52.5" y2="5.8"/&gt;
  &lt;circle cx="78" cy="14.7" r="8.653323061113575"/&gt;
  &lt;ellipse cx="102" cy="14.7" rx="10.5" ry="7.5"/&gt;
  &lt;rect x="117" y="7.5" fill="none" stroke="#E3000F" width="15" height="15"/&gt;
  &lt;line x1="135" y1="15" x2="142.5" y2="15"/&gt;
  &lt;line x1="142.5" y1="15" x2="142.5" y2="18"/&gt;
&lt;/svg&gt;

&lt;h3&gt;Length report&lt;/h3&gt;
&lt;textarea  id="lengthReport" &gt;&lt;/textarea&gt;</code></pre>
